  public func traverse<V: SwiftProtobuf.Visitor>(visitor: inout V) throws {
    if self.confidence != 0 {
      try visitor.visitSingularFloatField(value: self.confidence, fieldNumber: 1)
    }
    if self.value != .unspecified {
      try visitor.visitSingularEnumField(value: self.value, fieldNumber: 2)
    }
    try unknownFields.traverse(visitor: &visitor)
  }

  public static func ==(lhs: Insurance_EntityGender, rhs: Insurance_EntityGender) -> Bool {
    if lhs.confidence != rhs.confidence {return false}
    if lhs.value != rhs.value {return false}
    if lhs.unknownFields != rhs.unknownFields {return false}
    return true
  }
